//! CHEST source recommendation previews and independently scoped full-guideline links.
use super::pmc_crosswalk::{self as cw,Lookup,Planned,SourceRef};
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{Block,BlockKind,GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{blocks_from_html,sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::{HashSet,VecDeque};
use url::Url;
pub struct Chest;
const ROOT:&str="https://www.chestnet.org/guidelines-and-topic-collections/guidelines";
fn source(raw:&str,base:&Url)->Result<(Vec<(String,String)>,Vec<String>)>{let d=Html::parse_document(raw);let root=d.select(&sel(".basic-sections")).next().context("CHEST source content root missing")?;let mut seen=HashSet::new();let mut docs=vec![];let mut groups=vec![];for a in root.select(&sel("a[href]")){let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)) else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!seen.insert(url.clone()){continue}let p=u.path();if p.starts_with("/guidelines-and-topic-collections/guidelines/")&&p.trim_end_matches('/').split('/').count()>=5 {docs.push((url,text_of(&a)));}else if p.starts_with("/guidelines/")&&p.trim_end_matches('/').split('/').count()==3{groups.push(url)}}if docs.is_empty()&&groups.is_empty(){bail!("CHEST page has no source-emitted clinical topic or category links")};Ok((docs,groups))}
fn summary(raw:&str,base:&Url)->Result<(String,String,Vec<String>,Vec<serde_json::Value>,Option<usize>,Option<String>)>{let d=Html::parse_document(raw);let root=d.select(&sel(".basic-sections")).next().context("CHEST topic content missing")?;let title=root.select(&sel("h1 span.h2")).next().map(|e|text_of(&e)).context("CHEST topic title missing")?;let feature=root.select(&sel("#feature")).next().context("CHEST key recommendation feature missing")?;if !feature.select(&sel("h3")).any(|h|text_of(&h)=="Key Recommendations"){bail!("CHEST feature is not source-labelled Key Recommendations")};let recs=feature.select(&sel("p")).map(|p|text_of(&p)).filter(|s|!s.is_empty()).collect::<Vec<_>>();if recs.is_empty(){bail!("CHEST key recommendations empty")};let mut links=vec![];for a in root.select(&sel("a[href]")){let label=text_of(&a);if label.eq_ignore_ascii_case("ACCESS THE FULL GUIDELINE"){if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){links.push(json!({"url":url,"role":"full_guideline","label":label,"rights":"unknown"}));}}}
 let text=text_of(&root);let lower=text.to_lowercase();let expected=if lower.contains("eight evidence-based recommendations"){Some(8)}else if lower.contains("nine evidence-based recommendations"){Some(9)}else{None};let published=root.select(&sel(".category")).map(|x|text_of(&x)).find(|s|s.to_uppercase().starts_with("PUBLISHED "));Ok((title,root.html(),recs,links,expected,published))}
fn issue(src:&SourceEntry,url:String,msg:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("chest-{}-unresolved",common::short_hash(&url)),url,title:None,rendition:None,version:None,extra:json!({"discovery_error":msg})}}
#[async_trait::async_trait]
impl Adapter for Chest{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let root=src.catalog_url.as_deref().unwrap_or(ROOT);let mut queue=VecDeque::from([root.to_string()]);let mut pages=HashSet::new();let mut topics=HashSet::new();let mut rows=cw::enumerate(src,f,"chest",limit,&HashSet::new()).await?;if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}let mut pmcids:HashSet<String>=rows.iter().filter_map(cw::row_pmcid).collect();while let Some(url)=queue.pop_front(){if !pages.insert(url.clone()){continue}if pages.len()>100{rows.push(issue(src,url,"CHEST category bound exceeded".into()));break}let p=match f.get_ok(&url).await{Ok(p)=>p,Err(e)=>{rows.push(issue(src,url,format!("CHEST category unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){break}continue}};let base=Url::parse(&p.record.final_url)?;if base.origin()!=Url::parse(ROOT)?.origin(){bail!("CHEST category redirected outside source")};let(docs,groups)=match source(&p.text(),&base){Ok(x)=>x,Err(e)=>{rows.push(issue(src,url,format!("CHEST category template: {e:#}")));continue}};for g in groups{if !pages.contains(&g){queue.push_back(g)}}for (topic,_)in docs{if !topics.insert(topic.clone()){continue}let page=match f.get_ok(&topic).await{Ok(p)=>p,Err(e)=>{rows.push(issue(src,topic,format!("CHEST source topic unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let u=Url::parse(&page.record.final_url)?;if u.origin()!=base.origin(){rows.push(issue(src,topic,"CHEST topic redirected outside source".into()));continue}let(title,body,recs,links,expected,published)=match summary(&page.text(),&u){Ok(x)=>x,Err(e)=>{rows.push(issue(src,topic,format!("CHEST preview template: {e:#}")));continue}};let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&recs,&links,&expected,&published))?.as_bytes());let row=PlanRow{source_id:src.id.clone(),doc_key:format!("chest-{}-{}",common::short_hash(&topic),&hash[..12]),url:topic.clone(),title:Some(title.clone()),rendition:Some("html".into()),version:None,extra:json!({"snapshot":hash,"role":"source_preview"})};rows.push(row);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}for link in &links{let Some(asset)=link["url"].as_str() else{continue};
 // The source's "Access the full guideline" link states a PII; Crossref maps it to the DOI, and an Open Access
 // PMC copy (if any) is used through the shared crosswalk. Otherwise the journal outcome stays recorded.
 let mut crosswalk="no PII/DOI stated by the source link".to_string();
 let doi=match (cw::doi_from_url(asset),cw::pii_from_url(asset)){(Some(d),_)=>Some((d,"source_doi")),(None,Some(pii))=>match cw::doi_for_pii(f,&pii).await{Ok(Some(d))=>Some((d,"source_pii_crossref")),Ok(None)=>{crosswalk=format!("PII {pii}: no unique Crossref match");None}Err(e)=>{crosswalk=format!("PII {pii}: Crossref lookup failed: {e:#}");None}},_=>None};
 if let Some((doi,route))=doi{let sref=SourceRef{source_url:asset.into(),evidence_url:Some(topic.clone()),source_title:Some(title.clone()),item_type:Some("clinical_practice_guideline".into()),key_prefix:"chest".into(),id_route:route.into(),notes:vec![]};
  match cw::plan(src,f,Lookup::Doi(doi.clone()),sref,json!({"source_preview":topic,"source_doi":doi})).await?{Planned::Open(row)=>{if !pmcids.insert(cw::row_pmcid(&row).unwrap_or_default()){continue}rows.push(row);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}Planned::Closed{reason,..}=>crosswalk=format!("DOI {doi} ({route}): {reason}")}}
 let msg=match f.get_ok(asset).await{Err(e)=>format!("CHEST full guideline unavailable: {e:#}; open-access crosswalk: {crosswalk}"),Ok(_)=>format!("CHEST full guideline terminal returned bytes but its full source template and rights are unvalidated; open-access crosswalk: {crosswalk}")};let mut r=issue(src,asset.into(),msg);r.title=Some(title.clone());r.extra["source_preview"]=json!(topic);rows.push(r);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}}
  Ok(rows)
 }
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if cw::is_crosswalk_row(row){return cw::extract(src,f,row).await}if let Some(e)=row.extra["discovery_error"].as_str(){bail!("CHEST discovery: {e}")};let p=f.get_ok(&row.url).await?;let u=Url::parse(&p.record.final_url)?;if u.origin()!=Url::parse(ROOT)?.origin(){bail!("CHEST topic redirected outside source")};let(title,body,recs,links,expected,published)=summary(&p.text(),&u)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&recs,&links,&expected,&published))?.as_bytes());if row.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("CHEST preview changed; re-plan")};let(mut blocks,mut warnings)=blocks_from_html(&body,Some(&u),None);for(i,text)in recs.iter().enumerate(){blocks.push(Block{block_id:format!("chest-source-key-recommendation-{}",i+1),kind:BlockKind::Recommendation{label:None,strength:None,certainty:None,population:None,grading_system:None,qualifier:Some("Key Recommendations: publisher preview".into())},text:text.clone(),heading_path:vec!["Key Recommendations".into()],page:None})}warnings.push(format!("CHEST source page is a preview: {} key recommendations displayed; publisher reports {} total. Complete guideline and publisher rights require independent terminal access.",recs.len(),expected.map(|x|x.to_string()).unwrap_or_else(||"an unverified number of".into())));let dates=published.map(|s|vec![common::date("Source published",s.trim_start_matches("PUBLISHED "),&row.url)]).unwrap_or_default();Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:Some(format!("chest-{}",common::short_hash(&row.url))),title,url:row.url.clone(),item_type:Some("recommendation_summary".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Source preview and full journal article have separate, unverified rights.".into()),..Default::default()},date_observations:dates,blocks,attachments:links,fetches:vec![p.record],warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/chest_guidelines/catalog.html"));const TOB:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/chest_guidelines/tobacco.html"));const OSA:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/chest_guidelines/pregnancy.html"));
 #[test]fn genuine_preview_retains_three_of_eight(){let(docs,groups)=source(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert!(docs.iter().any(|(u,_)|u.ends_with("/tobacco-treatment-in-the-inpatient-setting")));assert!(groups.iter().any(|u|u.ends_with("/guidelines/clinical-pulmonary")));let(title,_,r,links,n,date)=summary(TOB,&Url::parse(ROOT).unwrap()).unwrap();assert!(title.contains("Tobacco Treatment"));assert_eq!(n,Some(8));assert_eq!(r.len(),3);assert!(r[0].contains("varenicline")&&r[1].contains("counseling")&&r[2].contains("postdischarge"));assert!(links[0]["url"].as_str().unwrap().contains("S0012-3692(26)06538-4"));assert!(date.unwrap().contains("SEPTEMBER 2, 2026"));let(_,_,r,_,n,_)=summary(OSA,&Url::parse(ROOT).unwrap()).unwrap();assert_eq!(n,Some(9));assert!(r.len()<9);}
 #[tokio::test]async fn source_preview_offline_retains_partial_and_full_error(){let url="https://www.chestnet.org/guidelines-and-topic-collections/guidelines/clinical-pulmonary/tobacco-treatment-in-the-inpatient-setting";let(tmp,f)={let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();(t,f)};f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests(url,TOB.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"chest_guidelines","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=Chest.discover(&src,&f,None).await.unwrap();let r=rows.iter().find(|r|r.url==url).unwrap();let d=Chest.extract(&src,&f,r).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("recommendation_summary"));assert_eq!(d.blocks.iter().filter(|b|matches!(b.kind,BlockKind::Recommendation{..})).count(),3);assert!(d.warnings.iter().any(|w|w.contains("3 key recommendations displayed")&&w.contains("8 total")));assert!(rows.iter().any(|r|r.extra["source_preview"]==url&&r.extra["discovery_error"].is_string()));drop(tmp);}
 #[test]fn actual_source_categories_emit_distinct_topic_links(){let clinical=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/chest_guidelines/clinical-pulmonary.html"));let airway=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/chest_guidelines/airway-disorders.html"));let (c,_)=source(clinical,&Url::parse("https://www.chestnet.org/guidelines-and-topic-collections/guidelines/clinical-pulmonary").unwrap()).unwrap();assert!(c.iter().any(|(u,_)|u.ends_with("/respiratory-management-of-patients-with-neuromuscular-weakness")));let (a,_)=source(airway,&Url::parse("https://www.chestnet.org/guidelines-and-topic-collections/guidelines/airway-disorders").unwrap()).unwrap();assert!(a.iter().any(|(u,_)|u.ends_with("/biologic-management-in-severe-asthma-for-adults")));}

}
